```js
const jobs = new Map(); // job_id -> {status: 'running' | 'cancelled'}

export async function listTools() {
  return [
    {
      name: 'start_job',
      description: 'Start a job with the given job_id. Returns running status. Rejects duplicate active jobs.',
      inputSchema: {
        type: 'object',
        properties: {
          job_id: { type: 'string', description: 'Unique identifier for the job' }
        },
        required: ['job_id'],
        additionalProperties: false
      }
    },
    {
      name: 'cancel_job',
      description: 'Cancel an active job with the given job_id. Changes an active job to cancelled. Rejects missing jobs or repeated cancellation.',
      inputSchema: {
        type: 'object',
        properties: {
          job_id: { type: 'string', description: 'Unique identifier for the job' }
        },
        required: ['job_id'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name === 'start_job') {
    return startJob(args);
  }
  if (name === 'cancel_job') {
    return cancelJob(args);
  }
  throw new Error('Method not found');
}

function validateJobId(args) {
  if (typeof args.job_id !== 'string' || args.job_id.length === 0) {
    throw new Error('job_id is required and must be a non-empty string');
  }
}

function startJob(args) {
  validateJobId(args);
  const job = jobs.get(args.job_id);
  if (job && job.status === 'running') {
    throw new Error(`job ${args.job_id} is already running`);
  }
  jobs.set(args.job_id, { status: 'running' });
  return {
    content: [{ type: 'text', text: `job ${args.job_id} is running` }]
  };
}

function cancelJob(args) {
  validateJobId(args);
  const job = jobs.get(args.job_id);
  if (!job) {
    throw new Error(`job ${args.job_id} not found`);
  }
  if (job.status === 'cancelled') {
    throw new Error(`job ${args.job_id} is already cancelled`);
  }
  job.status = 'cancelled';
  return {
    content: [{ type: 'text', text: `job ${args.job_id} cancelled` }]
  };
}
```

